head.script:
scwin.initScreen = function() {
	widgetControler1.addWidgets({
		id: "wgc01_Calendar",
		title: "Calendar",
		src: "/sample/common_link/widgetContainer_Dynamic_SKT-306_(WSQ-944)_calendar.xml",
		scope: true,
		unitWidth: 3,
		unitHeight: 1,
		x: 1,
		y: 0
	});
	log = "Completed initScreen";
};

scwin.onpageload2 = function() {
	window.log = undefined;
	scwin.initScreen();
	// Jira: wframe 에서도 동적 로딩(setSrc) 시 pending 없어야 함(첨부 wframeSample.xml)
	wfm_main.setSrc("/sample/common_link/widgetContainer_Dynamic_SKT-306_(WSQ-944)_calendar.xml");
};
